head.script:
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        txb_BndMktactTpCd.hide();
        edt_ListAmt.hide();
        edt_CoupnRt.hide();
        edt_FstIntPayDd.hide();
        edt_IsuDd.hide();
        edt_IntPayCalcMms.hide();

        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Top);
        $c.bns.BnsPanelToGroupBox(panel_1);
        $c.bns.BnsPanelToGroupBox(panel_2);

        // 호출파라미터설정
        scwin.setParam();

        // 목록복사
        scwin.copy();

        // 기본값은 최종
        rdo_PARAM.setValue("L");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90032.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

