        txb_AmtHan.setValue($c.bns.fn_ChgAmtToHan(edt_ListAmt.getValue()));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90032.edt_ListAmt_onkeyup" });
