///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name btn_Calc
 * @description 이자지급액 계산버튼
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Calc = async function() {
    // 이자지급액 초기화
    edt_PrincPayAmt.setValue("");

    // 계산전 검증
    if (!await scwin.checkValidation()) {
        return;
    }
    let bndOddllotddIntBas = 0;
    // 단수일 이자기준 구하기, 코드를 값으로 변경
    if (txb_BndOddllotddIntBasTpCd.getValue() === "1") {
        bndOddllotddIntBas = 360;
    } else if (txb_BndOddllotddIntBasTpCd.getValue() === "2") {
        bndOddllotddIntBas = 365;
    } else if (txb_BndOddllotddIntBasTpCd.getValue() === "3") {
        bndOddllotddIntBas = 366;
    }
    let rdoParam = rdo_PARAM.getValue(); // 라디오 선택값
    let listAmt = edt_ListAmt.getValue(); // 상장금액
    let coupnRt = edt_CoupnRt.getValue(); // 표면이자율
    let fstIntPayDd = edt_FstIntPayDd.getValue(); // 최초이자지급일
    let isuDd = edt_IsuDd.getValue(); // 발행일
    let intPayCalcMms = edt_IntPayCalcMms.getValue(); // 이자계산주기

    // 최초 이자계산
    if (rdoParam === "F") {
        // (최초이자지급일 - 발행일) 날짜 차이 계산 (일 단위)
        let timeDiff = $c.ut.cGetDifTodayInputdayBnd(fstIntPayDd, isuDd);
        calcIntPayAmt = (listAmt * (coupnRt * 100000) * (timeDiff / bndOddllotddIntBas)) / (100000 * 100);

        // 중간 이자계산

    } else if (rdoParam === "M") {
        calcIntPayAmt = (listAmt * (coupnRt * 100000) * (intPayCalcMms / 12)) / (100000 * 100);
    } else if (rdoParam === "L") {
        const lastIntPayDd = dts_List.getCellData(dts_List.getRowCount(), 'INT_PAY_DD');
        const lastIntPayDd_1 = dts_List.getCellData(dts_List.getRowCount() - 1, 'INT_PAY_DD');

        // (마지막차수 이자지급일 - 마지막 전회차 이자지급일) 날짜 차이 계산 (일 단위)
        let timeDiff = $c.ut.cGetDifTodayInputdayBnd(lastIntPayDd, lastIntPayDd_1);
        calcIntPayAmt = (listAmt * (coupnRt * 100000) * (timeDiff / bndOddllotddIntBas)) / (100000 * 100);
    }

    // 이자원단위 미만처리에따라 이자 보정..
    if (txb_IntUdwonProcsCd.getValue() === "1") {
        // 절사
        calcIntPayAmt = Math.floor(calcIntPayAmt);
    } else if (txb_IntUdwonProcsCd.getValue() === "2") {
        // 절상
        calcIntPayAmt = Math.ceil(calcIntPayAmt);
    } else if (txb_IntUdwonProcsCd.getValue() === "3") {
        // 사사오입
        calcIntPayAmt = Math.round(calcIntPayAmt);
    } else if (txb_IntUdwonProcsCd.getValue() === "4") {
        // 원미만인정

    }

    // 결과값 표시
    edt_PrincPayAmt.setValue(calcIntPayAmt);
};

/**
 * @method
 * @name checkValidation
 * @description 이자계산전 검증
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValidation = async function() {
    if (rdo_PARAM.getValue() === "") {
        await $c.win.alert("계산기준을 선택하세요.");
        rdo_PARAM.focus();
        return false;
    }

    // 고정금리-이표채 and 단수일이자기준 is not null인 경우만 최초,중간,최종 이자계산 가능.
    // else 중간만 계산 가능.
    // 단수일이자기준 : 1 - 360일 / 2 - 365일 / 3 - 366일
    if (rdo_PARAM.getValue() === "F" || rdo_PARAM.getValue() === "L") {
        // 이자지급방법 : 13(고정금리-이표채), 단수일이자기준 : 2(365일)
        if (txb_IntPayMethdCd.getValue() !== "13") {
            await $c.win.alert("[고정금리형-이표채]만 최초/최종 이자계산이 가능합니다.");
            return false;
        }
        if (txb_BndOddllotddIntBasTpCd.getValue() === "") {
            await $c.win.alert("단수일이자기준값이 없습니다.\n최초/최종 이자계산이 불가합니다.");
            return false;
        }
    }
    let rdoParam = rdo_PARAM.getValue(); // 라디오 선택값
    let listAmt = edt_ListAmt.getValue(); // 상장금액
    let coupnRt = edt_CoupnRt.getValue(); // 표면이자율
    let fstIntPayDd = edt_FstIntPayDd.getValue(); // 최초이자지급일
    let isuDd = edt_IsuDd.getValue(); // 발행일
    let intPayCalcMms = edt_IntPayCalcMms.getValue(); // 이자계산주기

    // 필수값 체크
    if (listAmt === "") {
        await $c.win.alert("상장금액이 없습니다.");
        return false;
    }
    if (coupnRt === "") {
        await $c.win.alert("표면이자율이 없습니다.");
        return false;
    }

    // 최초 이자계산
    if (rdoParam === "F") {
        if (isuDd === "") {
            await $c.win.alert("발행일이 없습니다.");
            return false;
        }
        if (fstIntPayDd === "") {
            await $c.win.alert("최초이자지급일이 없습니다.");
            return false;
        }

        // 중간 이자계산

    } else if (rdoParam === "M") {
        if (intPayCalcMms === "") {
            await $c.win.alert("이자계산주기값이 없습니다.");
            return false;
        }
    } else if (rdoParam === "L") {
        if (dts_List.getRowCount() < 2) {
            await $c.win.alert("차수가 2개 미만인 경우 '최종' 이자계산이 불가합니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name copy
 * @description 원리금 정보를 복사한다.
 * @returns {void}
 * @hidden N
 */
scwin.copy = function() {
    let prt = $c.frame.path("../");
    // copy (fromDataSet, toDataSet)
    $c.stf.copyDataSet(prt.dts_Princint, dts_List);
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    let prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        const arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        txb_BndMktactTpCd.setValue(arrPar[0].BND_MKTACT_TP_CD);
        edt_ListAmt.setValue(arrPar[0].LIST_AMT);
        edt_CoupnRt.setValue(arrPar[0].COUPN_RT);
        edt_FstIntPayDd.setValue(arrPar[0].FST_INT_PAY_DD);
        edt_IsuDd.setValue(arrPar[0].ISU_DD);
        edt_IntPayCalcMms.setValue(arrPar[0].INT_PAY_CALC_MMS);
        txb_IntPayMethdCd.setValue(arrPar[0].INT_PAY_METHD_CD);
        txb_BndOddllotddIntBasTpCd.setValue(arrPar[0].BND_ODDLLOTDD_INT_BAS_TP_CD);
        txb_IntUdwonProcsCd.setValue(arrPar[0].INT_UDWON_PROCS_CD);
    }
};
